import{_ as t,l as n,o as e,c as i,v as o,p as c,x as s,d as l,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"容器的 OS 含义","description":"","frontmatter":{"title":"容器的 OS 含义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-os.md","filePath":"cs/container-os.md","lastUpdated":1789023840000}'),h={name:"cs/container-os.md"};function u(m,a,_,f,S,E){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="容器的-os-含义" tabindex="-1">容器的 OS 含义 <a class="header-anchor" href="#容器的-os-含义" aria-label="Permalink to &quot;容器的 OS 含义&quot;">​</a></h1><div class="epigraph"><p>容器不是第二台内核：它是命名空间中的视图、cgroup 中的配额，加上一个用户空间根文件系统。</p><footer>—— 据 Linux 容器相关文档；Tanenbaum 对虚拟化与容器对照的整理</footer></div><p><a href="/cs/cgroups">上一课</a>给了配额，<a href="/cs/namespaces">namespaces</a> 给了视图。<a href="/cs/init-userspace">init</a> 可以在 pid 空间里再跑一个 1 号。<a href="/cs/vfs">VFS</a> 的绑定挂载把主机目录接到容器根。缺口是<strong>收束定义</strong>：工程上的「容器」= 这些 OS 原语的打包，对比下一课才开始的真虚拟机（客内核）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把容器说成轻量虚拟机，会误以为有独立页表根与独立中断。实际上：同一 <a href="/cs/user-kernel-split">用户/内核分裂</a>，同一系统调用表，除非再加过滤。隔离强度弱于 VM：内核漏洞是共享的。收益是启动快、密度高、不模拟设备。缺口：讲清打包（镜像只是 rootfs + 元数据），运行时负责 clone 标志、cgroup 路径、网卡进 net ns。本课不写编排器。</p><p><span class="marginnote">seccomp、capabilities、只读挂载是常见加固，下一课专讲系统调用过滤。本课不给逃逸清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行时：<code>clone</code> 新 ns、配 cgroup、pivot_root 到镜像、exec 入口。网络：veth 一对进 net ns，外层接网桥——链路层细节留给网络课，这里只承认「另一份网络栈视图」。存储：overlay 等联合挂载是 VFS 功能，不是新内核。</p>',8)),(e(),c(d,null,{default:s(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22rootfs%20%E9%95%9C%E5%83%8F%22%5D%20--%3E%20NS%5B%22namespaces%20%E8%A7%86%E5%9B%BE%22%5D%0A%20%20NS%20--%3E%20CG%5B%22cgroup%20%E9%85%8D%E9%A2%9D%22%5D%0A%20%20CG%20--%3E%20EXEC%5B%22exec%20%E5%85%A5%E5%8F%A3%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容器把本 OS 课从进程到挂载的对象组合起来，而不引入客机页表。它解释了为何「容器里 cat /proc/cpuinfo」仍是主机 CPU：没有 trap-and-emulate。下一课缩小系统调用面；再下一课才是真正的敏感指令陷入。</p><p>与过度提交、页 Cache 共用主机内存：cgroup 只是上限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 gVisor 等用户态内核。不把 OCI 规范当必背。下一课：即便 ns 切了，系统调用号仍通到同一内核——用过滤器裁面。</p><p>后课默认：容器共享内核。按系统调用号拦截，下一课 seccomp。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容器 = namespaces + cgroups + 用户态 rootfs，共享内核。</li><li>不是客机，没有独立特权 ISA 视图。</li><li>系统调用过滤是 seccomp 的缺口。</li><li>出处：Linux namespaces/cgroup 文档；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const g=t(h,[["render",u]]);export{b as __pageData,g as default};
